"""
FMP API Client for value-dividend-screener

Provides rate-limited access to Financial Modeling Prep API endpoints.

Features:
- Rate limiting (0.3s between requests)
- Automatic retry on 429 errors
- Session caching for duplicate requests
- Stable-only dividend/value routing and response aliases
"""

import os
import re
import sys
import time
from datetime import datetime, timedelta
from typing import Optional
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

try:
    import requests
except ImportError:
    print("ERROR: requests library not found. Install with: pip install requests", file=sys.stderr)
    sys.exit(1)

# Mirror of scripts/provider_contracts.py::redact_url (clients are standalone).
# Requires a `?`/`&` prefix, so this masks apikey=/api_key= in URL query
# strings, not a rendered params dict (unreachable today: only
# RequestException text -- which can embed the full request URL -- is
# ever printed here, never a bare params repr()).
_APIKEY_RE = re.compile(r"([?&](?:apikey|api_key)=)[^&\s]+", re.IGNORECASE)


def _redact_key(text: str) -> str:
    """Mask apikey=/api_key= query values so stderr never carries the key."""
    return _APIKEY_RE.sub(r"\1REDACTED", str(text))


# --- FMP endpoint fallback: stable (new users) -> v3 (legacy users) ---


def _et_today(now=None):
    """America/New_York calendar date for provider query windows (issue #427).

    An explicit aware ``now`` wins (deterministic runs/tests); otherwise the
    current instant is converted to America/New_York. ``now`` must be
    timezone-aware when supplied. Fail-closed: missing TZ data raises
    RuntimeError naming the tzdata requirement instead of silently falling
    back to the runner's local clock.
    """
    try:
        tz = ZoneInfo("America/New_York")
    except ZoneInfoNotFoundError as exc:
        raise RuntimeError("America/New_York timezone data is missing; pip install tzdata") from exc
    if now is not None:
        if now.tzinfo is None:
            raise ValueError("now must be timezone-aware")
        return now.astimezone(tz).date()
    return datetime.now(tz).date()


def _stable_hist_url(base, symbols_str, params):
    """stable/historical-price-eod/full?symbol=^GSPC&from=...&to=..."""
    params["symbol"] = symbols_str
    # New stable EOD endpoint ignores `timeseries`; convert to from/to range
    # to bound the payload. Use 2x calendar days to cover N trading days
    # (trading-day/calendar-day ratio ~252/365 ~0.69, so *2 leaves headroom).
    days = params.pop("timeseries", None)
    if days is not None:
        today = _et_today()
        params["from"] = (today - timedelta(days=int(days) * 2)).isoformat()
        params["to"] = today.isoformat()
    return base, params


def _v3_hist_url(base, symbols_str, params):
    """api/v3/historical-price-full/^GSPC?timeseries=80"""
    return f"{base}/{symbols_str}", params


_FMP_ENDPOINTS = {
    "historical": [
        ("https://financialmodelingprep.com/stable/historical-price-eod/full", _stable_hist_url),
        ("https://financialmodelingprep.com/api/v3/historical-price-full", _v3_hist_url),
    ],
}


def _normalize_eod_flat_list(data, symbols_str: str, limit: Optional[int] = None):
    """Convert stable/historical-price-eod/full flat list to v3-compatible dict.

    Input  : [{"symbol": "SPY", "date": "...", "open": ..., ...}, ...]
    Output : {"symbol": "SPY", "historical": [{"date": ..., "open": ..., ...}, ...]}

    Returns the input unchanged if not a list (passthrough for v3 dict /
    historicalStockList responses). Returns None when no row matches the
    requested symbol; the caller will record the failure and try the next
    endpoint.

    If `limit` is provided (the original `timeseries=N` request), the
    `historical` list is truncated to the first `limit` entries. The new
    EOD endpoint ignores `timeseries` and returns the full available history,
    so the caller's date-range bounding plus this truncation together preserve
    the legacy "most-recent N rows" contract. Truncation assumes descending
    date order, which the FMP EOD endpoint provides (verified live).

    Note: empty list ``[]`` does not reach this normalizer because the caller's
    ``if not data: continue`` falsy check handles it earlier in
    ``_request_with_fallback``.
    """
    if not isinstance(data, list):
        return data
    if not data:
        return None
    norm_target = symbols_str.replace("-", ".")
    matched_symbol = None
    historical = []
    for row in data:
        if not isinstance(row, dict):
            continue
        # Be permissive: single-symbol endpoint may omit per-row "symbol".
        # Treat missing symbol as belonging to the requested symbols_str.
        row_sym = row.get("symbol") or symbols_str
        if row_sym.replace("-", ".") != norm_target:
            continue
        matched_symbol = matched_symbol or row_sym
        historical.append({k: v for k, v in row.items() if k != "symbol"})
    if not historical:
        return None
    if limit is not None and limit > 0:
        historical = historical[:limit]
    return {"symbol": matched_symbol or symbols_str, "historical": historical}


class FMPClient:
    """Client for Financial Modeling Prep API with rate limiting and caching"""

    BASE_URL = "https://financialmodelingprep.com/api/v3"
    RATE_LIMIT_DELAY = 0.3  # 300ms between requests

    _ENDPOINT_FAILURE_THRESHOLD = 3  # disable endpoint after N consecutive failures
    STABLE_URL = "https://financialmodelingprep.com/stable"

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = (api_key or os.getenv("FMP_API_KEY") or "").strip()
        if not self.api_key:
            raise ValueError(
                "FMP API key required. Set FMP_API_KEY environment variable "
                "or pass api_key parameter."
            )
        self.session = requests.Session()
        self.session.headers.update({"apikey": self.api_key})
        self.timeout = 30
        self.cache = {}
        self.last_call_time = 0
        self.rate_limit_reached = False
        self.retry_count = 0
        self.max_retries = 1
        self.api_calls_made = 0
        # Circuit breaker: track consecutive failures per endpoint URL prefix
        self._endpoint_failures: dict[str, int] = {}
        self._disabled_endpoints: set[str] = set()
        # Most recent transport-level failure reason; set by _rate_limited_get
        # so _request_with_fallback can surface suppressed errors even when
        # an endpoint was called with quiet=True.
        self._last_error: Optional[str] = None

    def _redact_secret(self, text) -> str:
        """Mask raw and URL-encoded key echoes before diagnostics are truncated."""
        from urllib.parse import quote, quote_plus

        text = _redact_key(text)
        if not self.api_key:
            return text
        patterns = {re.escape(self.api_key)}
        for encoded in (quote(self.api_key, safe=""), quote_plus(self.api_key, safe="")):
            # Percent triplets are case-insensitive; the key's letters are not.
            parts = re.split(r"(%[0-9A-Fa-f]{2})", encoded)
            patterns.add(
                "".join(
                    "(?i:" + re.escape(part) + ")"
                    if re.fullmatch(r"%[0-9A-Fa-f]{2}", part)
                    else re.escape(part)
                    for part in parts
                )
            )
        # One pass prevents a short key from matching the replacement marker.
        return re.sub("|".join(sorted(patterns, key=len, reverse=True)), "***REDACTED***", text)

    def _rate_limited_get(
        self,
        url: str,
        params: Optional[dict] = None,
        quiet: bool = False,
        *,
        _json_retry: bool = True,
    ) -> Optional[dict]:
        self._last_error = None
        if self.rate_limit_reached:
            self._last_error = "daily rate limit already reached"
            return None

        if params is None:
            params = {}

        elapsed = time.time() - self.last_call_time
        if elapsed < self.RATE_LIMIT_DELAY:
            time.sleep(self.RATE_LIMIT_DELAY - elapsed)

        try:
            response = self.session.get(url, params=params, timeout=self.timeout)
            self.last_call_time = time.time()
            self.api_calls_made += 1

            if response.status_code == 200:
                self.retry_count = 0
                try:
                    data = response.json()
                except ValueError as e:
                    # Malformed 200 body: retry once per call chain, then fail
                    # soft with a redacted reason instead of raising. The retry
                    # adds no backoff beyond the normal rate-limit delay and
                    # costs one extra API call (counts against any budget).
                    msg = self._redact_secret(f"invalid JSON response: {e}")
                    if _json_retry:
                        if not quiet:
                            print(f"WARNING: {msg}; retrying once", file=sys.stderr)
                        return self._rate_limited_get(url, params, quiet=quiet, _json_retry=False)
                    self._last_error = msg
                    if not quiet:
                        print(f"ERROR: {msg}", file=sys.stderr)
                    return None
                return data
            elif response.status_code == 429:
                self.retry_count += 1
                if self.retry_count <= self.max_retries:
                    print("WARNING: Rate limit exceeded. Waiting 60 seconds...", file=sys.stderr)
                    time.sleep(60)
                    return self._rate_limited_get(url, params, quiet=quiet, _json_retry=_json_retry)
                else:
                    self._last_error = "HTTP 429 (daily rate limit)"
                    print("ERROR: Daily API rate limit reached.", file=sys.stderr)
                    self.rate_limit_reached = True
                    return None
            else:
                body = self._redact_secret(response.text)[:200]
                msg = self._redact_secret(f"HTTP {response.status_code} - {body}")
                self._last_error = msg
                if not quiet:
                    print(
                        f"ERROR: API request failed: {msg}",
                        file=sys.stderr,
                    )
                return None
        except requests.exceptions.RequestException as e:
            redacted = self._redact_secret(str(e))
            self._last_error = f"request exception: {redacted}"
            print(f"ERROR: Request exception: {redacted}", file=sys.stderr)
            return None

    def _request_with_fallback(self, endpoint_key, symbols_str, extra_params=None):
        """Try stable endpoint first, fall back to v3 for legacy users.

        Returns parsed JSON in v3-compatible shape, or None if all fail.
        Non-last endpoints are called with quiet=True so the user isn't
        alarmed by an expected stable failure when v3 will catch it — but
        when a non-last endpoint DOES fail, a WARN line is emitted explaining
        why we're falling back. Otherwise users only see the (often misleading)
        last-endpoint error and have no clue what really went wrong.
        """
        params = dict(extra_params) if extra_params else {}
        endpoints = _FMP_ENDPOINTS[endpoint_key]
        is_single = "," not in symbols_str

        for i, (base_url, url_builder) in enumerate(endpoints):
            # Circuit breaker: skip endpoints with too many consecutive failures
            if base_url in self._disabled_endpoints:
                continue

            url, final_params = url_builder(base_url, symbols_str, dict(params))
            is_last = i == len(endpoints) - 1
            data = self._rate_limited_get(url, final_params, quiet=not is_last)
            if not data:  # falsy (None, [], {}) — try next endpoint
                self._record_endpoint_failure(base_url)
                self._warn_fallback(base_url, is_last, self._last_error)
                continue

            # Normalize new stable EOD flat-list shape to v3-compatible dict.
            # No-op for v3 dict / historicalStockList responses.
            # `timeseries` (original request) is passed as `limit` so the
            # EOD endpoint's full-history response is truncated to the
            # legacy "most-recent N rows" contract.
            if endpoint_key == "historical":
                limit = params.get("timeseries") if isinstance(params, dict) else None
                data = _normalize_eod_flat_list(data, symbols_str, limit=limit)
                if not data:
                    self._record_endpoint_failure(base_url)
                    self._warn_fallback(
                        base_url,
                        is_last,
                        f"response had no rows matching '{symbols_str}'",
                    )
                    continue

            # Shape validation: reject truthy-but-wrong-shape responses
            valid = True
            shape_issue: Optional[str] = None
            if endpoint_key == "historical":
                if not isinstance(data, dict):
                    valid = False
                    shape_issue = "expected dict"
                elif "historicalStockList" in data:
                    # stable batch format -> v3 single format (exact match only)
                    norm = symbols_str.replace("-", ".")
                    found = None
                    for entry in data["historicalStockList"]:
                        if entry.get("symbol", "").replace("-", ".") == norm:
                            found = {
                                "symbol": entry.get("symbol"),
                                "historical": entry.get("historical", []),
                            }
                            break
                    if found:
                        self._endpoint_failures[base_url] = 0
                        return found
                    valid = False
                    shape_issue = f"'{symbols_str}' not in historicalStockList"
                elif "historical" not in data:
                    valid = False
                    shape_issue = "missing 'historical' key"
                elif is_single and data.get("symbol"):
                    if data["symbol"].replace("-", ".") != symbols_str.replace("-", "."):
                        valid = False
                        shape_issue = (
                            f"response symbol '{data['symbol']}' != requested '{symbols_str}'"
                        )

            if valid:
                self._endpoint_failures[base_url] = 0
                return data
            self._record_endpoint_failure(base_url)
            self._warn_fallback(base_url, is_last, shape_issue or "unexpected response shape")
        return None

    def _warn_fallback(self, base_url: str, is_last: bool, reason: Optional[str]) -> None:
        """Emit a WARN line so users see why a non-last endpoint failed and the
        client is falling back. No-op when the failing endpoint is the last one
        (its error was already printed by _rate_limited_get with quiet=False)."""
        if is_last or not reason:
            return
        print(
            f"WARN: {base_url} failed ({reason}); falling back to next endpoint",
            file=sys.stderr,
        )

    def _record_endpoint_failure(self, base_url: str) -> None:
        """Track consecutive failures and disable endpoint after threshold."""
        failures = self._endpoint_failures.get(base_url, 0) + 1
        self._endpoint_failures[base_url] = failures
        if failures >= self._ENDPOINT_FAILURE_THRESHOLD:
            self._disabled_endpoints.add(base_url)

    def _request(self, url: str, params: dict, quiet: bool = False):
        """Compatibility entry point; HTTP/retry/redaction stays in the shared core."""
        return self._rate_limited_get(url, params=params, quiet=quiet)

    def _get(self, endpoint: str, params: Optional[dict] = None):
        """Route the dividend callers' existing names to supported stable endpoints."""
        if self.rate_limit_reached:
            return None
        query = dict(params or {})
        is_dividend = endpoint.startswith("historical-price-full/stock_dividend/")
        if is_dividend:
            name = "dividends"
            query["symbol"] = endpoint.rsplit("/", 1)[-1]
        elif endpoint == "stock-screener":
            name = "company-screener"
        else:
            name, separator, symbol = endpoint.partition("/")
            if separator:
                query["symbol"] = symbol
        allowed = {
            "company-screener",
            "income-statement",
            "balance-sheet-statement",
            "cash-flow-statement",
            "key-metrics",
            "ratios",
            "profile",
            "quote",
            "dividends",
        }
        if name not in allowed:
            # Endpoint strings are internal, but never interpolate an unknown
            # caller value into the URL or error text.
            print("ERROR: Unsupported dividend client endpoint", file=sys.stderr)
            return None
        data = self._request(f"{self.STABLE_URL}/{name}", query)
        if data is None:
            return None
        return self._normalize(endpoint, data)

    @staticmethod
    def _normalize(endpoint: str, data):
        """Keep legacy reader aliases without changing provider scale or sign."""
        if data is None:
            return None
        if endpoint.startswith("historical-price-full/stock_dividend/"):
            return {"historical": data} if isinstance(data, list) else data
        name = endpoint.partition("/")[0]
        if isinstance(data, list):
            for record in data:
                if not isinstance(record, dict):
                    continue
                if name == "key-metrics" and "roe" not in record and "returnOnEquity" in record:
                    record["roe"] = record["returnOnEquity"]
                if (
                    name == "cash-flow-statement"
                    and "dividendsPaid" not in record
                    and "netDividendsPaid" in record
                ):
                    record["dividendsPaid"] = record["netDividendsPaid"]
        return data

    def get_dividend_prices(self, symbol: str, days: int = 30) -> Optional[list[dict]]:
        """Most-recent-first history for the dividend adapters; no retired v3 retry."""
        url = f"{self.STABLE_URL}/historical-price-eod/full"
        if url in self._disabled_endpoints:
            return None
        today = _et_today()
        data = self._request(
            url,
            {
                "symbol": symbol,
                "from": (today - timedelta(days=days * 2 + 10)).isoformat(),
                "to": today.isoformat(),
            },
        )
        if isinstance(data, list) and data:
            self._endpoint_failures[url] = 0
            return data[:days]
        self._record_endpoint_failure(url)
        return None

    def get_historical_prices(self, symbol: str, days: int = 30) -> Optional[list[dict]]:
        """Fetch historical daily OHLCV data for a symbol.

        Args:
            symbol: Ticker symbol
            days: Number of trading days to fetch (default: 30)

        Returns:
            List of price dicts (most-recent-first) or None on failure.
        """
        cache_key = f"prices_{symbol}_{days}"
        if cache_key in self.cache:
            return self.cache[cache_key]

        data = self._request_with_fallback("historical", symbol, {"timeseries": days})
        if data and "historical" in data:
            result = data["historical"]
            self.cache[cache_key] = result
            return result
        return None

    def get_api_stats(self) -> dict:
        """Return API usage statistics."""
        return {
            "cache_entries": len(self.cache),
            "api_calls_made": self.api_calls_made,
            "rate_limit_reached": self.rate_limit_reached,
        }
